use App\Dto\PlaceOrderRequest;
use Symfony\Component\HttpKernel\Attribute\MapRequestPayload;

#[Route('/api/orders', name: 'api_order_create', methods: ['POST'])]
public function create(#[MapRequestPayload] PlaceOrderRequest $payload, OrderPlacer $placer): JsonResponse
{
    $order = $placer->place($payload->email, $payload->sku, $payload->quantity);

    return $this->json(['id' => $order->getId()], 201);
}
